```css
/* ===========================================================
   ngx-datatable -> visual de DataTable Bootstrap
   Copie este arquivo como app/table/custom-datatable.css
   e cadastre-o uma única vez (ver seção "como registrar").
   Ajuste as variáveis :root para casar exatamente com seu
   DataTable original.
   =========================================================== */

/* --- paleta base (troque conforme seu tema original) --- */
:root {
  --tbl-bg:                #ffffff;
  --tbl-header-bg:         #e9ecef;
  --tbl-border:            #ced4da;
  --tbl-header-border:     #adb5bd;
  --tbl-row-alt:           #f8f9fa;
  --tbl-active-bg:         #0d6efd;
  --tbl-active-text:       #ffffff;
  --tbl-text:              #212529;
  --tbl-muted:             #6c757d;
  --tbl-subtle:            #495057;
  --tbl-link:              #0d6efd;
  --tbl-font:              system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
  --tbl-row-h:             36px;   /* altura aproximada das linhas */
}

*, *::before, *::after {
  box-sizing: border-box;
}

body {
  font-family: var(--tbl-font);
  color: var(--tbl-text);
  font-size: 0.875rem;
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
}

/* ----------------------------------------------------------
   1. Contêiner principal do DataTable (wrapper)
   ---------------------------------------------------------- */
.dt-wrapper-wrapper {
  max-width: 1200px;
  margin: 0 auto;
  font-size: var(--tbl-font-size-root, 0.875rem);
}

/* ----------------------------------------------------------
   2. Barra de ferramentas (busca, grupo de ações)
   ---------------------------------------------------------- */
.dt-row-toolbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.5rem;
  background: var(--tbl-bg);
  border-bottom: 1px solid var(--tbl-border);
  padding: 0.6rem 1rem;
  border-radius: 0.25rem;
}
.dt-tools {
  display: flex;
  align-items: center;
  gap: 0.25rem;
}

/* busca/filtro */
.dt-tools dt-search input {
  min-width: 240px;
  padding: 0.35rem 0.6rem;
  border: 1px solid var(--tbl-border);
  border-radius: 0.25rem;
  font-family: var(--tbl-font);
  font-size: inherit;
  line-height: 1.4;
  color: var(--tbl-text);
  background: var(--tbl-bg);
  transition: border-color .15s ease, box-shadow .15s ease;
  outline: none;
}
.dt-tools dt-search input:focus {
  border-color: var(--tbl-active-bg);
  box-shadow: 0 0 0 0.2rem rgba(var(--tbl-active-r, 13, 110, 243), .25);
}
.dt-tools dt-search input::placeholder {
  color: var(--tbl-muted);
}

/* ícones botões pequenos (ajuste se necessário) */
.dt-toolbar-sep {
  display: flex;
  align-items: center;
  margin: 0 0.4rem;
  color: var(--tbl-muted);
  line-height: 1;
}

/* ----------------------------------------------------------
   3. Cabeçalho da tabela (nome das colunas)
   ---------------------------------------------------------- */
.dt-th {
  -webkit-user-select: none;
  user-select: none;
  cursor: pointer;
  background: var(--tbl-header-bg);
  color: var(--tbl-text);
  font-weight: 600;
  font-size: 0.8125rem;
  line-height: 1.3;
  padding: 0.5rem 0.9rem;
  letter-spacing: -.02em;
  white-space: nowrap;
  text-rendering: optimizeLegibility;
  border-bottom: 2px solid var(--tbl-header-border);
  border-right: 1px solid transparent;
  position: relative;
  display: flex;
  align-items: center;
  gap: 0.2em;
}
.dt-th:hover,
[ngx-dt-sortable] th:hover {
  background: #dee2e6;
}

/* indicador de ordenação (chevrons) */
.DT_Sorter::after {
  content: "\2026"; /* ">" (seta vazada) */
  font-size: 0.6em;
  color: var(--tbl-muted);
  line-height: 1;
  margin-left: 0.1em;
  transition: color .15s ease;
}
/* coluna ordenada asc (confirme a classe usada pela sua versão; teste no DevTools) */
.dt-sort-ascending .DT_Sorter::after,
.dt-sorted-asc .DT_Sorter::after {
  content: "\25B6"; /* seta preenchida */
  color: var(--tbl-active-bg);
}
.dt-sort-descending .DT_Sorter::after,
.dt-sorted-desc .DT_Sorter::after {
  content: "\2026\x2025"; /* "<>" invertido */
  color: var(--tbl-active-bg);
}

/* ----------------------------------------------------------
   4. Tabela interna (recebe os dados do DataTables)
   ---------------------------------------------------------- */
.dth-table-wrap {
  background: var(--tbl-bg);
  border: 1px solid var(--tbl-border);
  border-radius: 0.25rem;
  overflow: hidden;
}
.dth-table {
  width: 100%;
  border-collapse: collapse;
  border-spacing: 0;
  table-layout: fixed;
  font-size: var(--tbl-font-size-body, 0.875rem);
}
.dth-scroll::-webkit-scrollbar { width: 10px; height: 10px; }
.dth-scroll::-webkit-scrollbar-track { background: #f3f4f6; }
.dth-scroll::-webkit-scrollbar-thumb { background: #adb5bd; border-radius: 5px; }
.dth-scroll::-webkit-scrollbar-thumb:hover { background: #aaa; }

/* ----------------------------------------------------------
   5. Células e linhas
   ---------------------------------------------------------- */
.dt-td {
  padding: 0.55rem 1rem;
  vertical-align: top;
  color: var(--tbl-text);
  line-height: 1.45;
  border-bottom: 1px solid var(--tbl-border);
}
.dt-td:last-of-type { border-bottom: none; }
.dt-td.tight, .dtr-row.tight .dt-td { padding: 0.4rem 1rem; }

/* zebra striping (escopo seguro dentro da tabela) */
.dth-table > tbody > tr:nth-child(even) .dt-td {
  background: var(--tbl-row-alt);
}
/* destaque ao passar o mouse sobre a linha */
.dth-table tr:hover > .dt-td {
  background: #e9ecef;
}
/* seleção em múltiplos (se habilitada) */
.dt-checkbox-cell input[type=checkbox] {
  width: 18px;
  height: 18px;
  margin: 0 4px 0 0;
  accent-color: var(--tbl-active-bg);
  cursor: pointer;
}

/* ----------------------------------------------------------
   6. Rodapé (count/info, quando showFooter)
   ---------------------------------------------------------- */
.dt-footer {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 0.55rem 1rem;
  border-top: 1px solid var(--tbl-border);
  background: #f8f9fa;
  font-size: 0.8125rem;
  color: var(--tbl-subtle);
}

/* ----------------------------------------------------------
   7. Paginação
   ---------------------------------------------------------- */
.dt-pagination {
  display: flex;
  justify-content: center;
  align-items: center;
  padding: 0.6rem 0 0;
  border-top: 1px solid var(--tbl-border);
  background: #f8f9fa;
}
.dt-pagination button,
.dt-pagination [type="button"] {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 36px;
  height: 36px;
  padding: 0.22rem 0.45rem;
  border: 1px solid var(--tbl-border);
  border-radius: 0.2rem;
  background: var(--tbl-bg);
  color: var(--tbl-subtle);
  font-family: var(--tbl-font);
  font-size: 0.78rem;
  font-weight: 500;
  line-height: 1.2;
  cursor: pointer;
  user-select: none;
  white-space: nowrap;
  transition: all .15s ease;
}
.dt-pagination button:hover,
.dt-pagination [type="button"]:hover {
  background: #e9ecef;
