/* ==================================================================
   CUSTOM-DATATABLE.CSS  — ngx-datatable com visual de DataTable Bootstrap
   Autor sugerido: adapte a paleta (:root) para igualar seu DataTable original.
   Como funciona: o ngx-datatable não injeta classes do Bootstrap nos seus
   elementos internos; ele usa classes próprias (dth-table-wrap, dt-th, dt-td
   etc.). Este CSS registra essas regras via DtRegisterStyles para "vestir" o
   componente. Registre-o UMA vez (serviço global ou por componente).
   ================================================================== */

/* --- Paleta ajustável (igual a do seu DataTable original) --- */
:root {
  --tbl-bg:                #ffffff;
  --tbl-header-bg:         #e9ecef;
  --tbl-border:            #ced4da;
  --tbl-header-border:     #adb5bd;
  --tbl-row-alt:           #f8f9fa;
  --tbl-active:            #0d6efd;  /* azul Bootstrap */
  --tbl-active-text:       #ffffff;
  --tbl-text:              #212529;
  --tbl-muted:             #6c757d;
  --tbl-subtle:            #495057;
  --tbl-font:              system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  --tbl-row-height:        36px;
}

*, *::before, *::after { box-sizing: border-box; }

body {
  font-family: var(--tbl-font);
  font-size: 0.875rem;
  color: var(--tbl-text);
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

/* ---------------------------------------------------------------
   1. Container externo (wrapper)
   --------------------------------------------------------------- */
.dt-wrapper-wrapper {
  max-width: 1200px;
  margin: 0 auto;
  padding: 1rem;
}

/* ---------------------------------------------------------------
   2. Barra de ferramentas + filtro (toolbar)
   --------------------------------------------------------------- */
.dt-toolbar-row,
.dt-row-toolbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.5rem;
  background: var(--tbl-bg);
  border: 1px solid transparent;
  border-bottom: 1px solid var(--tbl-border);
  padding: 0.6rem 1rem;
  border-radius: 0.25rem;
}

.dt-tools {
  display: flex;
  align-items: center;
  gap: 0.25rem;
}

.dt-tools dt-search input {
  min-width: 240px;
  padding: 0.3rem 0.6rem;
  border: 1px solid var(--tbl-border);
  border-radius: 0.25rem;
  font-family: var(--tbl-font);
  font-size: 0.875rem;
  line-height: 1.4;
  color: var(--tbl-text);
  background: var(--tbl-bg);
  outline: none;
  transition: border-color .15s ease, box-shadow .15s ease;
}
.dt-tools dt-search input:focus {
  border-color: var(--tbl-active);
  box-shadow: 0 0 0 0.2rem rgba(var(--tbl-active-r, 13, var(--tbl-active-b, 243), .25));
}
.dt-tools dt-search input::placeholder { color: var(--tbl-muted); }

.dt-toolbar-sep {
  display: flex;
  align-items: center;
  margin: 0 0.4rem;
  color: var(--tbl-muted);
  line-height: 1;
}

/* ---------------------------------------------------------------
   3. Cabeçalho de colunas
   --------------------------------------------------------------- */
.dt-th {
  -webkit-user-select: none;
  user-select: none;
  cursor: pointer;
  background: var(--tbl-header-bg);
  color: var(--tbl-text);
  font-weight: 600;
  font-size: 0.8125rem;
  line-height: 1.3;
  padding: 0.5rem 0.9rem;
  letter-spacing: -.02em;
  white-space: nowrap;
  text-rendering: optimizeLegibility;
  border-bottom: 2px solid var(--tbl-header-border);
  border-right: 1px solid transparent;
  display: flex;
  align-items: center;
  gap: 0.15em;
}
.dt-th:hover,
[ngx-dt-sortable] th:hover {
  background: #dee2e6;
}

.dt-truncate {
  overflow: hidden;
  text-overflow: ellipsis;
}

/* indicador de ordenação */
.DT_Sorter::after {
  content: "\2026";   /* seta vazada ">" */
  font-size: 0.6em;
  color: var(--tbl-muted);
  line-height: 1;
  margin-left: 0.1em;
  transition: color .15s ease;
}
/* Ascendente */
.dt-sort-dir-asc .DT_Sorter::after,   /* confira a classe exata na sua versão */
.dt-sorted-asc .DT_Sorter::after      {
  content: "\25B6";   /* seta preenchida ▼... na verdade ↑ ASCII: \25B2 */
  color: var(--tbl-active);
