/* =========================================================================
   custom-datatable.css
   Estiliza o ngx-datatable com visual similar ao DataTable Bootstrap
   usado hoje na aplicação (tabelas reais <table>).

   Estratégia: o ngx-datatable não injeta classes do Bootstrap nos seus
   elementos (usa classes próprias: .dt-th, .dt-td, .dth-table-wrap etc.).
   Este arquivo registra os estilos via DtRegisterStyles e deve ser aplicado
   UMA única vez (serviço global ou no componente da tabela).

   Ajuste as variáveis de :root para reproduzir exatamente as cores, fonte e
   espaçamentos do seu DataTable original.
   ========================================================================= */

:root {
  --tbl-bg:                #ffffff;
  --tbl-header-bg:         #e9ecef;
  --tbl-border:            #ced4da;
  --tbl-header-border:     #adb5bd;
  --tbl-row-alt:           #f8f9fa;
  --tbl-active:            #0d6efd;
  --tbl-active-text:       #ffffff;
  --tbl-text:              #212529;
  --tbl-muted:             #6c757d;
  --tbl-subtle:            #495057;
  --tbl-font:              system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
}

*, *::before, *::after { box-sizing: border-box; }

body {
  font-family: var(--tbl-font);
  font-size: 0.875rem;
  color: var(--tbl-text);
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

/* 1. Container externo */
.dt-wrapper-wrapper {
  max-width: 1200px;
  margin: 0 auto;
  padding: 1rem;
}

/* 2. Barra de ferramentas + filtro */
.dt-row-toolbar,
.dt-toolbar-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
