## 2. Chamada do front-end (JavaScript)

No botão/input de cupom do carrinho ou checkout:

```js
$(document).ready(function () {
    $('#btn-cupom').on('click', function (e) {
        e.preventDefault();

        var codigo = $('#input-cupom').val().trim();
        if (!codigo) {
            $.notify(null, 'Por favor, informe o código do cupom.', {
                icon: 'fa fa-info-circle',
                type: 'warning'
            });
            return;
        }

        // Ajuste a URL conforme sua rota:
        // Se sua base gera rotas públicas: admin_url('coupons/apply_coupon')
        var url = $(this).data('url') || '/admin/coupons/apply_coupon';

        $.ajax({
            type:  'POST',
            url:   url,
            data:  { code: codigo },
            dataType: 'json',

            beforeSend: function () {
                $('#btn-cupom')
                    .prop('disabled', true)
                    .html('<i class="fa fa-spinner fa-spin"></i> Verificando o cupom...');
            },

            complete: function (response) {
                if (response.state === 'success') {
                    var cupom = response.data.coupon;

                    // Mantém os dados disponíveis para o cálculo do desconto no checkout
                    window.__cupomAplicado = cupom;

                    $('#input-cupom').prop('disabled', true);
                    $('#lbl-cupom-aplicado').text(cupom.code);

                    // Exibe a faixa de desconto (ajuste os IDs/CSS conforme seu template)
                    $('.faixa-desconto').css('background-color', '#28a745');
                } else {
                    $.notify(null, response.data ? response.data.message : response.message, {
                        icon: 'fa fa-times',
                        type: 'danger'
                    });

                    $('#btn-cupom').prop('disabled', false)
                                 .html('<i class="fa fa-plus"></i> Aplicar cupom');
                    $('#input-cupom').prop('disabled', false);
                }
            }
        });
    });
});
```

