/**
 * Valida/aplica um cupom enviado pelo cliente (checkout).
 * Retorna JSON: sucesso com dados do cupom OU erro detalhado.
 */
public function apply_coupon($code)
{
    $code = strtolower(trim($code));

    // 1. Existe o cupom?
    $coupon = $this->coupons_model->get_coupon_by_code($code);

    if (!$coupon) {
        return json_response([
            'success' => false,
            'message' => 'Código de cupom inválido ou não encontrado.',
            'detail'  => []
        ], 400);
    }

    // Padroniza datas retornadas pelo banco (pode vir como array ou string)
    if (is_array($coupon->valid_from)) {
        $coupon->valid_from = date('Y-m-d H:i:s', mktime(
            $coupon->valid_from['hour'], $coupon->valid_from['minute'],
            $coupon->valid_from['second'],
            $coupon->valid_from['month'], $coupon->valid_from['day'],
            $coupon->valid_from['year']
        ));
    }
    if (is_array($coupon->valid_to)) {
        $coupon->valid_to = date('Y-m-d H:i:s', mktime(
            $coupon->valid_to['hour'], $coupon->valid_to['minute'],
            $coupon->valid_to['second'],
            $coupon->valid_to['month'], $coupon->valid_to['day'],
            $coupon->valid_to['year']
        ));
    }

    $agora = time();

    // 2. Dentro do período de validade?
    if (!empty($coupon->valid_from) && $coupon->valid_from > $agora) {
        return json_response([
            'success' => false,
            'message' => 'Cupom ainda não está válido. Disponível a partir de: ' .
                date('d/m/Y H:i', $coupon->valid_from),
            'detail' => ['valid_from' => $coupon->valid_from]
        ], 422);
    }

    if (!empty($coupon->valid_to) && $coupon->valid_to < $agora) {
        return json_response([
            'success' => false,
            'message' => 'Cupom expirado. Válido somente até: ' .
                date('d/m/Y H:i', $coupon->valid_to),
            'detail' => ['valid_to' => $coupon->valid_to]
        ], 422);
    }

    // 3. Já foi usado? (somente se o cupom for de uso único)
    if (!$coupon->is_reusable && !empty($coupon->used_at) && $coupon->used_at < $agora) {
        return json_response([
            'success' => false,
            'message' => 'Este cupom já foi utilizado. Por favor, utilize outro.',
            'detail'  => ['usado_em' => $coupon->used_at]
        ], 409);
    }

    // Opcional: limite máximo de usos (ex.: usados 5x e acabou)
    // if (!empty($coupon->used_count) && $coupon->used_count >= $coupon->max_redemptions) {
