    //         'message' => 'Este cupom só pode ser utilizado por novos clientes.',
    //         'detail' => [], ], 403);
    // }

    // ✅ Cupom liberado!
    return json_response([
        'success' => true,
        'message' => 'Cupom aplicado com sucesso!',
        'data' => [
            'coupon' => [
                'id'          => (int) $coupon->id,
                'code'        => $coupon->code,
