//|                    Média Móvel Simples com Notificação            |
//+------------------------------------------------------------------+
#property copyright "Assistente MQL5"
#property version   "1.00"
#property strict
#property indicator_chart_window              // Indica que é um indicador para gráficos
#property indicator_buffers      1            // 1 buffer extra (a própria SMA)
#property indicator_plots       1             // 1 plot (linha da SMA)
#property indicator_style1      DRAW_LINE
#property indicator_color1      clrBlue
#property indicator_width1      2

// Parâmetros configuráveis
input int           SMA_Period      = 14;     // Período da Média Móvel
input double        Sensibilidade   = 5;      // Pontos de distância para acionar alerta
input bool          Notificacao     = true;   // Enviar notificação no celular?

// Buffers
double SMABuffer[];                            // Buffer da Média Móvel

datetime UltimoAlerta[1];                      // Evita avisos repetidos logo após um
int       ContadorAlerta = 0;

//+------------------------------------------------------------------+
//| Inicialização                                                     |
//+------------------------------------------------------------------+
int OnInit()
  {
   // Conecta o buffer dos dados da SMA ao gráfico (índice 0)
   SetIndexBuffer(0, SMABuffer, INDICATOR_DATA);

   // Define cor, estilo e espessura da linha da SMA
   IndicatorSetInteger(0, INDICATOR_GRAPHICAL_LINE_STYLE, STYLE_SOLID);
   IndicatorSetInteger(0, INDICATOR_GRAPHICAL_LINE_WIDTH, 2);
   IndicatorSetInteger(0, INDICATOR_GRAPHICAL_LINE_COLOR, (uint32)clrBlue);

   // Nome amigável no gráfico
   IndicatorSetString(0, INDICATOR_SHORTNAME, "SMA Alert (" + IntegerToString(SMA_Period) + ")");

   return(INIT_SUCCEEDED);
  }

//+------------------------------------------------------------------+
//| Cálculo Principal                                                 |
//+------------------------------------------------------------------+
int OnCalculate(const int rates_total,
                const int prev_calculated,
                const datetime &time[],
                const double &open[],
                const double &high[],
                const double &low[],
                const double &close[],
                const long &tick_volume[],
                const long &volume[],
                const int &spread[])
  {
   // Garante que temos candles suficientes para a média
   if (rates_total < SMA_Period + 1)
      return(0);

   // Calcula a Média Móvel Simples diretamente no buffer
   CalcularSMA(close, SMABuffer, SMA_Period, prev_calculated);

   // Verifica condições de alerta
   VerificarAlerta(rates_total, close, SMABuffer);

   return(rates_total);
  }

//+------------------------------------------------------------------+
//| Calcula a Média Móvel Simples                                     |
//+------------------------------------------------------------------+
void CalcularSMA(const double &price[],
                 double      &buffer[],
                 int         periodo,
                 int         desde)
  {
   int fim = MathMin(ArraySize(price) - 1, desde + periodo - 1);
   for (int i = desde; i <= fim; i++)
     {
      double soma = 0.0;
      for (int j = 0; j < periodo; j++)
        soma += price[i - j];               // Soma dos últimos 'periodo' candles
      buffer[i] = soma / periodo;           // Divide pela quantidade
     }
  }

//+------------------------------------------------------------------+
//| Lógica de Alerta                                                  |
//+------------------------------------------------------------------+
void VerificarAlerta(int rates_total,
                     const double &close[],
                     const double &sma[])
  {
   int ultimaBarr = rates_total - 1;

   // Ignora se ainda não temos dados válidos para a média
   if (ultimaBarr < SMA_Period)
      return;

   double precoAtual  = close[ultimaBarr];
   double valorSMA    = sma[ultimaBarr];
   double distancia   = MathAbs(precoAtual - valorSMA);

   // Distância mínima em pontos conforme o símbolo atual
   double minimaDistancia = Sensibilidade * _Point;

   // Só avisa se estiver dentro da faixa e não alertar nos últimos minutos
   if (distancia <= minimaDistancia && (UltimoAlerta[ContadorAlerta] == 0 ||
                                          TimeCurrent() - UltimoAlerta[ContadorAlerta] >= 60))
     {
      string mensagem = "Preço chegou perto da SMA(" +
                        IntegerToString(SMA_Period) + ")! Preço: " +
                        DoubleToString(precoAtual, _Digits);

      // Aviso visual no canto do MT5
      Alert(mensagem);

      // Notificação push para o celular (se configurada nas opções do MT5)
      if (Notificacao)
         SendNotification(mensagem);

      // Marca o horário do alerta para evitar disparos repetidos rápidos
      UltimoAlerta[ContadorAlerta++] = TimeCurrent();
     }
  }
//+------------------------------------------------------------------+
