//+------------------------------------------------------------------+
//| Calcula Média Móvel Simples                                       |
//+------------------------------------------------------------------+
void SimpleMovingAverage(const double &price[], 
                         double &result[], 
                         int period,
                         int start_from)
  {
   for (int i = start_from; i < ArraySize(price); i++)
     {
      double sum = 0.0;
      for (int j = 0; j < period; j++)
        sum += price[i - j];
      result[i] = sum / period;
     }
  }

