//| Checagem de Alert                                                 |
//+------------------------------------------------------------------+
void CheckAlert(int rates_total, const double &close[], const double &sma[])
  {
   // Usa o valor da SMA no candle anterior para comparação justa
   // Ou no próprio candle atual. Vamos usar o último disponível.
   int lastBar = rates_total - 1;

   // Se for o primeiro candle válido, pula
   if (lastBar < SMA_Period) return;

   double currentPrice = close[lastBar];
   double smaValue     = sma[lastBar];
   double distance     = MathAbs(currentPrice - smaValue);

   // Converte a sensibilidade para pontos usando o símbolo atual
   double minDistance = Sensibilidade * _Point;

   if (distance <= minDistance && LastAlertTime[AlertIndex] == 0)
     {
      string msg = "Preço próximo da SMA("+IntegerToString(SMA_Period)+")! Valor: "+DoubleToString(currentPrice,_Digits);

      // Alerta visual no topo do terminal
      Alert(msg);

      // Notificação push (se configurado no MT5)
      if (Notificacao)
         SendNotification(msg);

      LastAlertTime[AlertIndex++] = TimeCurrent();
     }
  }
